#!/usr/bin/env python3
"""Single-template planning_store shim generator (PRD 082 phase 10 / R27)."""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path
from typing import Any

SCRIPT_DIR = Path(__file__).resolve().parent
if str(SCRIPT_DIR) not in sys.path:
    sys.path.insert(0, str(SCRIPT_DIR))

from _sw.cli import run_module_main
from planning_import_inventory import CANONICAL_REL, build_inventory, load_inventory, repo_root

GENERATED_MARKER = "planning-store-shim/v1"
GENERATED_HEADER = (
    "# GENERATED BY planning_shim_gen.py — do not edit manually.\n"
    f"# Marker: {GENERATED_MARKER}\n"
)

SHIM_TARGETS: tuple[tuple[str, int], ...] = (
    ("core/scripts/planning_store.py", 2),
    ("dist/cursor/scripts/planning_store.py", 3),
    ("dist/claude-code/scripts/planning_store.py", 3),
)


def inventoried_symbol_names(inventory: dict[str, Any]) -> list[str]:
    symbols = inventory.get("symbols")
    if not isinstance(symbols, list):
        raise ValueError("inventory.symbols must be a list")
    names: list[str] = []
    for row in symbols:
        if not isinstance(row, dict):
            continue
        name = str(row.get("name") or "")
        if not name or name == "planning_store":
            continue
        names.append(name)
    return sorted(set(names))


def render_shim(*, repo_depth: int, symbol_names: list[str]) -> str:
    export_block = "\n".join(f"    {name!r}," for name in symbol_names)
    return f'''#!/usr/bin/env python3
"""Generated planning_store compatibility shim — re-exports the canonical module."""
from __future__ import annotations

import importlib.util
import sys
from pathlib import Path
from typing import Any

{GENERATED_HEADER.strip()}

_CANONICAL_MODULE_NAME = "_planning_store_canonical"
_CANONICAL_REL = "{CANONICAL_REL}"
_REPO_ROOT_DEPTH = {repo_depth}
_EXPORTED_NAMES = (
{export_block}
)
_cached: Any | None = None


def _repo_root() -> Path:
    return Path(__file__).resolve().parents[_REPO_ROOT_DEPTH]


def _load_canonical():
    global _cached
    if _cached is not None:
        return _cached
    path = _repo_root() / _CANONICAL_REL
    spec = importlib.util.spec_from_file_location(_CANONICAL_MODULE_NAME, path)
    if spec is None or spec.loader is None:
        raise ImportError(f"cannot load canonical planning store: {{path}}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[_CANONICAL_MODULE_NAME] = module
    spec.loader.exec_module(module)
    _cached = module
    return module


def __getattr__(name: str) -> Any:
    return getattr(_load_canonical(), name)


def __dir__() -> list[str]:
    return sorted(set(dir(_load_canonical())) | set(globals()) | set(_EXPORTED_NAMES))


def main() -> None:
    _load_canonical().main()


if __name__ == "__main__":
    main()
'''


def write_shim(root: Path, rel_target: str, content: str) -> Path:
    path = root / rel_target
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content, encoding="utf-8")
    return path


def generate_all(root: Path, inventory: dict[str, Any] | None = None) -> dict[str, Any]:
    inv = inventory if inventory is not None else build_inventory(root)
    names = inventoried_symbol_names(inv)
    written: list[str] = []
    for rel_target, depth in SHIM_TARGETS:
        content = render_shim(repo_depth=depth, symbol_names=names)
        out = write_shim(root, rel_target, content)
        written.append(out.relative_to(root).as_posix())
    return {
        "verdict": "pass",
        "action": "generate",
        "marker": GENERATED_MARKER,
        "symbolCount": len(names),
        "targets": written,
    }


def check_all(root: Path, inventory: dict[str, Any] | None = None) -> dict[str, Any]:
    inv = inventory if inventory is not None else load_inventory(root)
    names = inventoried_symbol_names(inv)
    mismatches: list[dict[str, str]] = []
    for rel_target, depth in SHIM_TARGETS:
        path = root / rel_target
        if not path.is_file():
            mismatches.append({"target": rel_target, "reason": "missing"})
            continue
        expected = render_shim(repo_depth=depth, symbol_names=names)
        actual = path.read_text(encoding="utf-8")
        if actual != expected:
            mismatches.append({"target": rel_target, "reason": "content-drift"})
    verdict = "pass" if not mismatches else "fail"
    return {
        "verdict": verdict,
        "action": "check",
        "mismatches": mismatches,
        "targetCount": len(SHIM_TARGETS),
    }


def cmd_generate(root: Path) -> int:
    payload = generate_all(root)
    print(json.dumps(payload, indent=2))
    return 0


def cmd_check(root: Path) -> int:
    payload = check_all(root)
    print(json.dumps(payload, indent=2))
    return 0 if payload["verdict"] == "pass" else 20


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(prog="planning_shim_gen.py")
    parser.add_argument("--root", default=".", help="Repository root")
    sub = parser.add_subparsers(dest="cmd", required=True)
    sub.add_parser("generate", help="Generate shims for core and dist trees")
    sub.add_parser("check", help="Verify generated shims match the template")
    args = parser.parse_args(list(sys.argv[1:] if argv is None else argv))
    try:
        root = repo_root(Path(args.root))
    except FileNotFoundError as exc:
        print(json.dumps({"verdict": "fail", "error": str(exc)}), file=sys.stderr)
        return 20
    try:
        if args.cmd == "generate":
            return cmd_generate(root)
        if args.cmd == "check":
            return cmd_check(root)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        print(json.dumps({"verdict": "fail", "error": str(exc)}), file=sys.stderr)
        return 20
    return 2


if __name__ == "__main__":
    run_module_main(main)
